  var CURATED_CACHE = {};

  function curatedFor(kind) {
    var list = CURATED_FALLBACK[kind] || [];
    CURATED_CACHE[kind] = list;
    return Promise.resolve(list);
  }

  function mergeCurated(extra, list) {
    var seen = {};
    var merged = [];
    (extra || []).forEach(function (item) {
      if (seen[item.id]) return;
      seen[item.id] = 1;
      merged.push(item);
    });
    list.forEach(function (item) {
      if (seen[item.id]) return;
      seen[item.id] = 1;
      merged.push(item);
    });
    return merged;
  }
  var media = {
    kind: 'movie',
    filter: 'trending',
    provider: '',
    query: '',
    mode: 'grid',
    items: [],
    page: 1,
    maxPage: 1,
    loadingMore: false,
    item: null,
    seasons: [],
    season: 1,
    episodeNum: 1,
    source: 'cinemaos',
    frame: null,
    stepTimer: 0
  };
  var mediaSearchTimer = null;
  var movieProgress = 0;
  var movieTarget = 0;
  var movieTicker = null;

  function movieStep(at, to, text) {
    movieProgress = Math.max(movieProgress, at);
    movieTarget = to;
    if (els.movieFill) els.movieFill.style.width = movieProgress + '%';
    if (text && els.movieStatus) els.movieStatus.textContent = text;
  }

  function movieTickerStart() {
    window.clearInterval(movieTicker);
    movieTicker = window.setInterval(function () {
      if (movieProgress >= movieTarget - 1) return;
      movieProgress += (movieTarget - movieProgress) * 0.08;
      if (els.movieFill) els.movieFill.style.width = movieProgress + '%';
    }, 180);
  }

  function movieDone() {
    window.clearInterval(movieTicker);
    movieStep(100, 100, 'Tap play');
    window.setTimeout(function () {
      if (els.movieLoad) {
        els.movieLoad.classList.add('done');
        /* Take it out of the layout as well: a transparent panel that is still
           present can swallow taps on slow devices. */
        els.movieLoad.hidden = true;
      }
      if (els.movieWrap) els.movieWrap.hidden = false;
    }, 420);
  }

  function movieReset(text) {
    window.clearInterval(movieTicker);
    movieProgress = 0;
    movieTarget = 0;
    if (els.movieFill) els.movieFill.style.width = '0%';
    if (els.movieLoad) {
      els.movieLoad.hidden = false;
      els.movieLoad.classList.remove('done');
    }
    if (text) movieStep(6, 40, text);
    movieTickerStart();
  }

  function mediaName(item) {
    return item.title || item.name || item.original_title || item.original_name || 'Untitled';
  }

  function mediaYear(item) {
    return String(item.release_date || item.first_air_date || '').slice(0, 4);
  }

  function mediaPoster(item) {
    var path = item.poster_path || item.backdrop_path || '';
    return path ? MEDIA_IMG + path : '';
  }

  function mediaCountLabel(n) {
    if (!els.mediaSub) return;
    els.mediaSub.textContent = n ? n + (n === 1 ? ' title' : ' titles') : '';
  }

  function mediaChipsMark() {
    els.mediaChips.forEach(function (chip) {
      var f = chip.getAttribute('data-filter');
      var ok = !!(MEDIA_FILTERS[media.kind] && MEDIA_FILTERS[media.kind][f]);
      chip.hidden = !ok;
      chip.setAttribute('aria-pressed', ok && f === media.filter && !media.provider ? 'true' : 'false');
    });
    els.providerChips.forEach(function (chip) {
      var p = chip.getAttribute('data-provider') || '';
      chip.setAttribute('aria-pressed', p === media.provider ? 'true' : 'false');
    });
  }

  function mediaChrome(view) {
    var grid = view === 'grid';
    media.mode = grid ? 'grid' : 'player';
    if (els.mediaGrid) els.mediaGrid.hidden = !grid;
    if (els.mediaFilters) els.mediaFilters.hidden = !grid;
    if (els.providerFilters) els.providerFilters.hidden = !grid;
    if (els.mediaSearch) els.mediaSearch.hidden = !grid;
    if (els.viewHead) els.viewHead.hidden = !grid;
    if (els.playerBar) els.playerBar.hidden = grid;
    /* Always leave a way out: from a movie it goes back to the list, from the
       list it goes back Home. */
    if (els.mediaBack) {
      els.mediaBack.hidden = false;
      els.mediaBack.textContent = grid ? 'Home' : 'Back';
    }
    if (grid) {
      if (els.seasonSel) { els.seasonSel.hidden = true; els.seasonSel.textContent = ''; }
      if (els.episodeSel) { els.episodeSel.hidden = true; els.episodeSel.textContent = ''; }
    }
  }

  function mediaFetch(path) {
    var url = MEDIA_API + path;
    return fetchWithTimeout(url, 14000).then(function (res) {
      if (!res.ok) throw new Error('media HTTP ' + res.status);
      return res.json();
    }).catch(function () {
      return fetchWithTimeout(cfUrl(url), 16000).then(function (res) {
        if (!res.ok) throw new Error('media HTTP ' + res.status);
        return res.json();
      });
    });
  }

  function renderMediaGrid(list, append) {
    if (!els.mediaGrid) return;
    if (!append) els.mediaGrid.textContent = '';
    var frag = document.createDocumentFragment();
    list.forEach(function (item) {
      var card = document.createElement('button');
      card.type = 'button';
      card.className = 'media-card';
      card.title = mediaName(item);

      var art = document.createElement('span');
      art.className = 'media-art';
      var src = mediaPoster(item);
      if (src) {
        var img = document.createElement('img');
        img.alt = '';
        img.loading = 'lazy';
        img.decoding = 'async';
        img.src = src;
        img.addEventListener('error', function () {
          img.remove();
          var mark = document.createElement('span');
          mark.className = 'media-fallback';
          mark.textContent = (mediaName(item)[0] || '?').toUpperCase();
          art.appendChild(mark);
        });
        art.appendChild(img);
      }

      var info = document.createElement('span');
      info.className = 'media-info';
      var name = document.createElement('span');
      name.className = 'media-name';
      name.textContent = mediaName(item);
      var year = document.createElement('span');
      year.className = 'media-year';
      year.textContent = mediaYear(item) || (media.kind === 'tv' ? 'TV' : 'Movie');

      info.appendChild(name);
      info.appendChild(year);
      card.appendChild(art);
      card.appendChild(info);
      card.addEventListener('click', function () { openMedia(item); });
      frag.appendChild(card);
    });
    els.mediaGrid.appendChild(frag);
    els.mediaGrid.hidden = false;
    mediaCountLabel(els.mediaGrid.querySelectorAll('.media-card').length);
  }

  /* ---------------- paging: the whole catalogue, not just page 1 ---------------- */

  function mediaPagePath(page) {
    var base;
    if (media.query) {
      base = '/search/' + (media.kind === 'tv' ? 'tv' : 'movie') +
        '?query=' + encodeURIComponent(media.query) + '&include_adult=false';
    } else if (media.provider) {
      base = '/discover/' + (media.kind === 'tv' ? 'tv' : 'movie') +
        '?with_watch_providers=' + encodeURIComponent(media.provider) +
        '&watch_region=' + MEDIA_REGION +
        '&sort_by=popularity.desc&vote_count.gte=100&include_adult=false';
    } else {
      base = MEDIA_FILTERS[media.kind][media.filter];
    }
    if (page <= 1) return base;
    return base + (base.indexOf('?') >= 0 ? '&' : '?') + 'page=' + page;
  }

  /* The catalogue is a popularity feed, but TMDB still slips brand-new or
     straight-to-video titles with a handful of votes into it. Those are the
     cards that looked like filler, so they are dropped unless the user asked
     for them by name. */
  function mediaTooObscure(item) {
    var votes = Number(item.vote_count) || 0;
    var pop = Number(item.popularity) || 0;
    if (votes >= 60) return false;
    return pop < 60;
  }

  function mediaParse(data, page) {
    var list = ((data && data.results) || []).filter(function (item) {
      if (!item || !item.id || !mediaPoster(item)) return false;
      if (!media.query && mediaTooObscure(item)) return false;
      return true;
    });
    var pages = Number(data && data.total_pages) || page;
    media.maxPage = Math.max(1, Math.min(pages, MEDIA_MAX_PAGE));
    return list;
  }

  function mediaRemember() {
    var key = media.kind + ':' + (media.query ? 'q:' + media.query : (media.provider ? 'p:' + media.provider : media.filter));
    MEDIA_CACHE[key] = {
      items: media.items,
      page: media.page,
      maxPage: media.maxPage,
      query: media.query,
      filter: media.filter,
      provider: media.provider
    };
  }

  function mediaSettled() {
    window.clearInterval(movieTicker);
    movieStep(100, 100, 'Ready');
    if (els.movieLoad) els.movieLoad.classList.add('done');
  }

  function mediaLoad(filter, force) {
    if (!els.mediaGrid) return Promise.resolve();
    var kind = media.kind;
    var key = kind + ':' + (media.query ? 'q:' + media.query : (media.provider ? 'p:' + media.provider : filter));
    media.filter = filter;
    media.query = '';
    media.page = 1;
    media.maxPage = 1;
    media.loadingMore = false;
    mediaChipsMark();
    movieReset(kind === 'tv' ? 'Loading shows' : 'Loading movies');

    var cached = MEDIA_CACHE[key];
    if (!force && cached) {
      media.items = cached.items;
      media.page = cached.page;
      media.maxPage = cached.maxPage;
      renderMediaGrid(media.items);
      mediaSettled();
      return Promise.resolve();
    }

    var fallback = CURATED_FALLBACK[kind] || [];
    /* Only the default Trending grid pins the hand-picked titles. A provider,
       anime or search request must show exactly what it asked for, otherwise
       every chip looks like it returns the same list. */
    var pinCurated = !media.provider && filter === 'trending';
    if (pinCurated && fallback.length) {
      media.items = fallback;
      renderMediaGrid(media.items);
      mediaSettled();
    } else if (els.mediaGrid) {
      els.mediaGrid.hidden = true;
    }
    return mediaFetch(mediaPagePath(1)).then(function (data) {
      var list = mediaParse(data, 1);
      if (!list.length) throw new Error('empty list');
      return curatedFor(kind).then(function (extra) {
        media.items = pinCurated ? mergeCurated(extra, list) : list;
        mediaRemember();
        renderMediaGrid(media.items);
        mediaSettled();
      });
    }).catch(function () {
      /* The catalogue API can be filtered even when the player is not. Keep the
         saved popular picks on screen so Movies/TV never comes up empty. */
      if (fallback.length) {
        media.items = fallback;
        mediaRemember();
        renderMediaGrid(media.items);
        mediaSettled();
        if (els.mediaSub) els.mediaSub.textContent = 'Saved picks · ' + fallback.length + ' titles';
        return;
      }
      window.clearInterval(movieTicker);
      if (els.movieStatus) els.movieStatus.textContent = 'Could not load the list. Try another tab.';
      if (els.movieFill) els.movieFill.style.width = '0%';
      if (els.movieLoad) {
        els.movieLoad.hidden = false;
        els.movieLoad.classList.remove('done');
      }
    });
  }

  /* Appends the next page in place. Uses the same path builder as page 1 so
     search results page too, and de-dupes ids TMDB repeats across pages. */
  function mediaMore() {
    if (media.mode !== 'grid' || media.loadingMore) return Promise.resolve();
    if (media.page >= media.maxPage) return Promise.resolve();
    media.loadingMore = true;
    var want = media.page + 1;
    if (els.mediaSub) els.mediaSub.textContent = 'Loading more…';

    return mediaFetch(mediaPagePath(want)).then(function (data) {
      if (want !== media.page + 1) return;
      var list = mediaParse(data, want);
      var seen = {};
      media.items.forEach(function (i) { seen[i.id] = 1; });
      var fresh = list.filter(function (i) { return !seen[i.id]; });
      media.page = want;
      if (fresh.length) {
        media.items = media.items.concat(fresh);
        renderMediaGrid(fresh, true);
      } else {
        mediaCountLabel(els.mediaGrid.querySelectorAll('.media-card').length);
      }
      mediaRemember();
    }).catch(function () {
      /* keep whatever is on screen; the scroll handler can retry */
      mediaCountLabel(els.mediaGrid.querySelectorAll('.media-card').length);
    }).then(function () {
      media.loadingMore = false;
    });
  }

  function openMedia(item) {
    media.item = item;
    media.seasons = [];
    media.season = 1;
    if (els.mediaTitle) els.mediaTitle.textContent = mediaName(item);
    var bits = [];
    var year = mediaYear(item);
    if (year) bits.push(year);
    if (item.vote_average) bits.push(Number(item.vote_average).toFixed(1) + '/10');
    bits.push('English');
    if (els.mediaSub) els.mediaSub.textContent = bits.join(' · ');
    if (els.playerName) els.playerName.textContent = mediaName(item);
    if (els.playerTags) els.playerTags.textContent = bits.join('  ·  ');
    mediaChrome('player');
    if (media.kind === 'tv') loadSeasons(item);
    else playMedia(1, 1);
  }

  function loadSeasons(item) {
    movieReset('Loading episodes');
    mediaFetch('/tv/' + item.id).then(function (data) {
      if (!media.item || media.item.id !== item.id) return;
      var seasons = ((data && data.seasons) || []).filter(function (s) {
        return s && s.season_number > 0 && s.episode_count > 0;
      });
      if (!seasons.length) throw new Error('no seasons');
      media.seasons = seasons;
      if (els.seasonSel) {
        els.seasonSel.textContent = '';
        seasons.forEach(function (s) {
          var opt = document.createElement('option');
          opt.value = String(s.season_number);
          opt.textContent = 'Season ' + s.season_number + ' (' + s.episode_count + ')';
          els.seasonSel.appendChild(opt);
        });
        els.seasonSel.hidden = false;
      }
      selectSeason(seasons[0].season_number, true);
    }).catch(function () {
      if (!media.item || media.item.id !== item.id) return;
      playMedia(1, 1);
    });
  }

  function selectSeason(number, autoplay) {
    media.season = number;
    if (els.seasonSel) { els.seasonSel.value = String(number); els.seasonSel.hidden = false; }
    if (els.episodeSel) { els.episodeSel.textContent = ''; els.episodeSel.hidden = true; }
    var id = media.item ? media.item.id : 0;
    mediaFetch('/tv/' + id + '/season/' + number).then(function (data) {
      if (!media.item || media.item.id !== id) return;
      var eps = ((data && data.episodes) || []).filter(function (e) { return e && e.episode_number; });
      if (!eps.length) throw new Error('no episodes');
      if (els.episodeSel) {
        eps.forEach(function (e) {
          var opt = document.createElement('option');
          opt.value = String(e.episode_number);
          opt.textContent = 'E' + e.episode_number + (e.name ? ' · ' + e.name : '');
          els.episodeSel.appendChild(opt);
        });
        els.episodeSel.hidden = false;
      }
      if (autoplay) playMedia(number, eps[0].episode_number);
    }).catch(function () {
      if (autoplay) playMedia(number, 1);
    });
  }

  /* ---- resolving the stream (no iframe) ---- */

  function loadScriptOnce(src, marker) {
    return new Promise(function (resolve, reject) {
      if (marker && window[marker]) { resolve(window[marker]); return; }
      var s = document.createElement('script');
      s.src = src;
      s.async = true;
      s.onload = function () {
        if (marker && !window[marker]) { reject(new Error('script empty')); return; }
        resolve(marker ? window[marker] : true);
      };
      s.onerror = function () { reject(new Error('script blocked')); };
      /* This app also runs as an SVG document, where document.head is null.
         The XHTML wrapper inside the foreignObject hosts scripts fine. */
      var mount = document.getElementById('saleen-root') ||
        document.head || document.documentElement;
      mount.appendChild(s);
    });
  }

  var hlsBoot = null;
  var hlsPlayer = null;
  var hlsBlob = null;
  var playerVideo = null;
  var VIX_CACHE = {};

  function loadHls() {
    if (window.Hls) return Promise.resolve(window.Hls);
    if (!hlsBoot) {
      hlsBoot = loadScriptOnce(HLS_JS, 'Hls').catch(function (err) {
        hlsBoot = null;
        throw err;
      });
    }
    return hlsBoot;
  }

  /* vixsrc's metadata endpoints are Cloudflare-protected and send no CORS
     headers, so the small JSON/HTML lookups go through public readers. The
     playlist itself is CORS-open, so the video segments come straight from
     the CDN and stream at full speed. */
  function vixText(url, accept) {
    var tries = [
      function (u) { return 'https://corsproxy.org/?' + encodeURIComponent(u); },
      function (u) { return 'https://api.codetabs.com/v1/proxy/?quest=' + encodeURIComponent(u); },
      function (u) { return 'https://api.allorigins.win/raw?url=' + encodeURIComponent(u); },
      function (u) { return cfUrl(u); },
      function (u) { return fastUrl(u); }
    ].map(function (make) {
      return function () {
        return fetchWithTimeout(make(url), 12000, { headers: { accept: accept || '*/*' } })
          .then(function (res) {
            if (!res.ok) throw new Error('meta ' + res.status);
            return res.text();
          });
      };
    });
    return firstOf(tries);
  }

  function vixPlaylistUrl(kind, id, season, episode) {
    var key = kind + ':' + id + ':' + season + ':' + episode;
    if (VIX_CACHE[key]) return VIX_CACHE[key];

    var api = kind === 'tv'
      ? VIX_API_TV + id + '/' + season + '/' + episode
      : VIX_API_MOVIE + id;

    var job = vixText(api, 'application/json').then(function (txt) {
      var data;
      try { data = JSON.parse(txt); } catch (e) { throw new Error('bad api'); }
      if (!data || !data.src) throw new Error('no source');
      return /^https?:/i.test(data.src) ? data.src : 'https://vixsrc.to' + data.src;
    }).then(function (embed) {
      return vixText(embed, 'text/html').then(function (html) {
        var token = (html.match(/'token':\s*'([^']+)'/) || [])[1] || '';
        var expires = (html.match(/'expires':\s*'([^']+)'/) || [])[1] || '';
        var playlist = (html.match(/url:\s*'([^']+)'/) || [])[1];
        if (!playlist) throw new Error('no playlist');
        return playlist + '?token=' + encodeURIComponent(token) +
          '&expires=' + encodeURIComponent(expires) + '&h=1&lang=en';
      });
    });

    VIX_CACHE[key] = job;
    job.catch(function () { delete VIX_CACHE[key]; });
    return job;
  }

  /* Keeps only the English audio rendition and drops every subtitle track, so
     the player has nothing to switch to. */
  function englishOnlyPlaylist(text) {
    var audio = '';
    var out = [];
    String(text || '').split(/\r?\n/).forEach(function (line) {
      if (/^#EXT-X-MEDIA:TYPE=SUBTITLES/i.test(line)) return;
      if (/^#EXT-X-MEDIA:TYPE=AUDIO/i.test(line)) {
        if (!audio && /LANGUAGE="eng"/i.test(line)) audio = line;
        return;
      }
      if (/^#EXT-X-STREAM-INF/i.test(line)) line = line.replace(/,SUBTITLES="[^"]*"/i, '');
      out.push(line);
    });
    if (audio) {
      var at = 0;
      while (at < out.length && !/^#EXT-X-STREAM-INF/i.test(out[at])) at += 1;
      out.splice(at, 0, audio);
    }
    return out.join('\n');
  }

  /* ---- vidrock: a CORS-open metadata endpoint that returns the real HLS
     playlist, encrypted with a key that ships in its own bundle. Decrypting it
     in the page means no relay, no iframe and no third party in the path. Its
     segments are MPEG-TS wrapped in a tiny PNG shell (a filter dodge on their
     side), so a custom hls.js loader peels the shell off before demuxing. */

  var VIDROCK_API = 'https://vidrock.net/api/';
  var VIDROCK_KEY = '7f3e9c2a8b5d1f4e6a9c3b7d2e5f8a1c4b6d9e2f5a8c1b4d7e9f2a5c8b1d4e7f';
  var vidrockKeyJob = null;

  function hexBytes(hex) {
    var out = new Uint8Array(hex.length / 2);
    for (var i = 0; i < out.length; i++) out[i] = parseInt(hex.substr(i * 2, 2), 16);
    return out;
  }

  function b64urlBytes(text) {
    var s = String(text || '').replace(/-/g, '+').replace(/_/g, '/');
    var pad = s.length % 4;
    if (pad === 2) s += '==';
    else if (pad === 3) s += '=';
    else if (pad === 1) throw new Error('bad base64');
    var bin = atob(s);
    var out = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  function vidrockKey() {
    if (!window.crypto || !window.crypto.subtle) return Promise.reject(new Error('no webcrypto'));
    if (!vidrockKeyJob) {
      vidrockKeyJob = window.crypto.subtle.importKey(
        'raw', hexBytes(VIDROCK_KEY), { name: 'AES-GCM' }, false, ['decrypt']
      ).catch(function (err) {
        vidrockKeyJob = null;
        throw err;
      });
    }
    return vidrockKeyJob;
  }

  function vidrockDecrypt(key, payload) {
    var raw = b64urlBytes(payload);
    if (raw.length < 28) return Promise.reject(new Error('short ciphertext'));
    return window.crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: raw.slice(0, 12) }, key, raw.slice(12)
    ).then(function (plain) {
      return new TextDecoder().decode(plain);
    });
  }

  /* Only English, HLS sources are considered. Nova is normally the English
     one; the loop just means a renamed slot still works. */
  function vidrockStream(kind, id, season, episode) {
    var path = kind === 'tv'
      ? 'tv/' + id + '/' + season + '/' + episode
      : 'movie/' + id;
    return fetchWithTimeout(VIDROCK_API + path, 9000, { headers: { accept: 'application/json' } })
      .then(function (res) {
        if (!res.ok) throw new Error('vidrock ' + res.status);
        return res.json();
      })
      .then(function (map) {
        var names = Object.keys(map || {}).filter(function (name) {
          var src = map[name];
          return src && src.url && /^hls$/i.test(src.type || '') &&
            /english/i.test(src.language || '');
        });
        if (!names.length) throw new Error('no english source');
        return vidrockKey().then(function (key) {
          /* Every mirror is decrypted up front. Some of them answer 403 to a
             plain fetch (they want a vidrock referer), so the player walks the
             whole list instead of trusting the first name. */
          return Promise.all(names.map(function (name) {
            return vidrockDecrypt(key, map[name].url).then(function (url) {
              if (!/^https?:\/\//i.test(url)) return null;
              return { url: url, name: name };
            }).catch(function () { return null; });
          })).then(function (list) {
            var out = list.filter(Boolean);
            if (!out.length) throw new Error('no url');
            return out;
          });
        });
      });
  }

  /* Strips the PNG wrapper: 64 bytes of fake 1x1 PNG in front, sometimes a
     trailer behind. Returns the TS payload on a 188-byte packet boundary. */
  function tsPayload(buffer) {
    var u = new Uint8Array(buffer);
    if (u[0] !== 0x89 || u[1] !== 0x50) return buffer;
    var start = -1;
    for (var i = 0; i < 600 && i + 188 * 8 < u.length; i++) {
      var ok = true;
      for (var k = 0; k < 8; k++) {
        if (u[i + 188 * k] !== 0x47) { ok = false; break; }
      }
      if (ok) { start = i; break; }
    }
    if (start < 0) return buffer;
    var keep = Math.floor((u.length - start) / 188) * 188;
    return u.slice(start, start + keep).buffer;
  }

  function pngLoader(Hls) {
    var Base = Hls.DefaultConfig.loader;
    return class PngLoader extends Base {
      load(context, config, callbacks) {
        var done = callbacks.onSuccess;
        callbacks.onSuccess = function (response, stats, ctx, net) {
          try {
            if (response && response.data instanceof ArrayBuffer) {
              response.data = tsPayload(response.data);
            }
          } catch (e) { }
          done(response, stats, ctx, net);
        };
        super.load(context, config, callbacks);
      }
    };
  }

  /* The stream hosts reject a browser request no matter which referer is sent:
     they fingerprint the presence of an Origin header. libcurl on the other
     side of the Wisp socket is a plain HTTP client, so playlists and segments
     can be pulled with the referer the CDN expects. */
  function wispLoader(Hls) {
    var Base = Hls.DefaultConfig.loader;
    return class WispLoader extends Base {
      constructor(config) {
        super(config);
